def largest_binary_subset(strs, m, n):
    dp = [[0]*(n+1) for _ in range(m+1)]
    for word in strs:
        zeros = word.count('0')
        ones = len(word)-zeros
        for z in range(m, zeros-1, -1):
            row, previous = dp[z], dp[z-zeros]
            for o in range(n, ones-1, -1):
                candidate = previous[o-ones]+1
                if candidate > row[o]:
                    row[o] = candidate
    return dp[m][n]

